    private static RequestSpec listRunsRequest(String companyId, AutomationsListRunsParams params) {
        QueryString query = new QueryString();
        if (params != null) {
            query.add("cursor", params.cursor().orElse(null));
            query.add("event_id", params.eventId().orElse(null));
            query.add("external_id", params.externalId().orElse(null));
            query.add("limit", params.limit().orElse(null));
            query.add("scenario", params.scenario().orElse(null));
        }
        return RequestSpec.of("GET", "/v1/companies/{co}/automations/runs", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/automations/runs")
            .query(query);
    }

